// 击穿防护：单飞 + TTL 抖动
public <T> T getOrLoad(String key, Supplier<T> loader) {
    String cached = redis.get(key);
    if (cached != null) return decode(cached);

    // SET lock:rebuild:<key> <token> NX PX 5000
    String token = UUID.randomUUID().toString();
    boolean ok = "OK".equals(redis.set(
        "lock:rebuild:" + key, token, "NX", "PX", 5000));
    if (ok) {
        try {
            T v = loader.get();
            int ttl = 60 + ThreadLocalRandom.current().nextInt(20);
            redis.setex(key, ttl, encode(v)); // TTL 抖动防雪崩
            return v;
        } finally {
            // Lua 释放：先校验 token 再 DEL，避免误删他人的锁
            redis.eval(
                "if redis.call('get', KEYS[1]) == ARGV[1] then " +
                "return redis.call('del', KEYS[1]) else return 0 end",
                1, "lock:rebuild:" + key, token);
        }
    } else {
        sleep(50 + ThreadLocalRandom.current().nextInt(50));
        return getOrLoad(key, loader); // 退避重试
    }
}

// 穿透防护：布隆过滤器前置
public <T> T getWithBloom(String key, Supplier<T> loader) {
    // BF.MEXISTS 返回 0 一定不存在，返回 1 才有误判
    List<Long> res = (List<Long>) redis.execute("BF.MEXISTS bf:user " + key);
    if (res == null || res.get(0) == 0L) return null;
    return getOrLoad(key, loader);
}
